[5341] = { en = "Barov Family Fortune", tier = 4,
  t = "Het familiefortuin van de Barovs",
  d = "In de Scholomance ligt het fortuin van de familie Barov. Ik, Alexi Barov, ben een van de laatste twee overgebleven erfgenamen van het huis Barov. Mijn broer Weldon is de andere.$B$BWeldon, die ellendige lafaard, vluchtte tijdens de oorlog. Zo bleef hij een mens en hield hij zijn waardeloze bestaan.$B$BNu zoekt hij de akten, zodat hij het fortuin voor zichzelf kan opeisen. Haal de akten terug voordat mijn broer dat doet, en ik maak je rijker dan in je wildste dromen!",
  o = "Ga naar de Scholomance en haal het familiefortuin van de Barovs terug. Dit fortuin bestaat uit vier akten: de Deed to Caer Darrow, de Deed to Brill, de Deed to Tarren Mill en de Deed to Southshore. Keer terug naar Alexi Barov als je deze taak hebt voltooid.",
  p = "Buig je hoofd in mijn aanwezigheid, $r. Ik ben tenslotte een edelman, en jij bent een boer zonder één koperstuk.",
  c = "Uitstekend werk, $R. Nu mijn erfenis nog veiligstellen...",
  g = { {"fortuin", "fortune"}, {"overgebleven", "remaining (overblijven)"}, {"erfgenamen", "heirs (erfgenaam)"}, {"ellendige", "miserable (ellendig)"}, {"lafaard", "coward"}, {"waardeloze", "worthless (waardeloos)"}, {"bestaan", "existence"}, {"akten", "deeds (akte)"}, {"opeisen", "claim"}, {"wildste", "wildest (wild)"}, {"Buig", "bow (buigen)"}, {"aanwezigheid", "presence"}, {"edelman", "noble(man)"}, {"koperstuk", "copper coin"}, {"erfenis", "inheritance"}, {"veiligstellen", "secure"} },
},

[7490] = { en = "Victory for the Horde", tier = 4,
  t = "Overwinning voor de Horde",
  d = "Je hebt het onmogelijke bereikt. De broedmoeder van de Black Dragonflight ligt dood aan je voeten. Neem haar hoofd en bied het aan je krijgsheer aan.",
  o = "Breng de Head of Onyxia naar Thrall in Orgrimmar.",
  p = "<Thralls onbewogen houding verandert heel even als hij het enorme hoofd van Onyxia ziet. De machtige Doomhammer werd bijna uit de schede getrokken.>",
  c = "Dit is een grote overwinning voor de Horde, $N. Zo vaak heb je je krijgsheer eer bewezen. Het is tijd dat de krijgsheer jou eert.",
  g = { {"het onmogelijke", "the impossible"}, {"bereikt", "accomplished (bereiken)"}, {"broedmoeder", "brood mother"}, {"bied het aan", "present it (aanbieden)"}, {"krijgsheer", "warchief"}, {"onbewogen", "stoic, unmoved"}, {"houding", "demeanour, attitude"}, {"schede", "sheath"}, {"getrokken", "drawn (trekken)"}, {"eer bewezen", "honoured (eer bewijzen)"}, {"eert", "honours (eren)"} },
},

[8367] = { en = "For Great Honor", tier = 4,
  t = "Voor grote eer",
  d = "Het is een grote eer om de Horde te dienen in een van de grote veldslagen tegen de Alliance! Maar alleen de weinigen die de Horde aan AL onze actieve fronten hebben gediend, zijn onze echt grote strijders. We zullen onze tegenstanders verslaan, niet door losse schermutselingen te vechten, maar door een goed gecoördineerde oorlog te voeren.$B$BGa op weg en verpletter de Alliance in Arathi Basin, Alterac Valley en Warsong Gulch! Voor de eer! Voor de Horde!",
  o = "Breng 3 Alterac Valley Marks of Honor, 3 Arathi Basin Marks of Honor en 3 Warsong Gulch Marks of Honor naar een Horde Warbringer buiten de slagvelden.",
  p = "Arathi is nog nat van het bloed van grote krijgers, en in heel Alterac klinkt nog het botsen van staal. Verspil mijn tijd niet, tenzij je nieuws van het front brengt!",
  c = "Je beproevingen waren niet makkelijk, maar je moed liet je niet in de steek en je kracht faalde niet. Neem afscheid van je oude tekens van overwinning, $C. Niemand heeft ze nodig om eraan herinnerd te worden hoeveel je waard bent. Sta rechtop, $N. Vandaag loop je met grote trots, want je bent een held!",
  g = { {"veldslagen", "battles (veldslag)"}, {"tegenstanders", "opponents (tegenstander)"}, {"schermutselingen", "skirmishes (schermutseling)"}, {"gecoördineerde", "coordinated (gecoördineerd)"}, {"verpletter", "crush (verpletteren)"}, {"slagvelden", "battlegrounds, battlefields (slagveld)"}, {"tenzij", "unless"}, {"botsen", "clashing (botsen)"}, {"beproevingen", "trials (beproeving)"}, {"liet je niet in de steek", "did not abandon you (in de steek laten)"}, {"faalde", "failed (falen)"}, {"Neem afscheid van", "part with, say goodbye to (afscheid nemen)"}, {"herinnerd", "reminded (herinneren)"}, {"rechtop", "upright, straight"}, {"trots", "pride"} },
},

[8731] = { en = "Field Duty", tier = 4,
  t = "Velddienst",
  d = "Gegroet, $N. Voordat ik je zwaardere taken in de oorlog geef, moet je eerst je deel van de velddienst doen.$B$BJe vindt de Orgrimmar Legion van Captain Skullsplit buiten Hive'Regal.$B$BMeld je bij hem en kom bij mij terug met bewijs van je velddienst. Dan heb ik een moeilijkere opdracht voor je klaar.$B$BO, en doe alsjeblieft je best om uit de buurt van de Ironforge Brigade te blijven. De spanningen tussen onze vrijwilligers van de Alliance en de Horde zijn hoog.",
  o = "Meld je bij Krug Skullsplit bij de post van de Orgrimmar Legion voor Hive'Regal. Zorg dat je Unsigned Field Duty Papers klaar hebt, haal Signed Field Duty Papers en breng ze naar Windcaller Kaldon in Cenarion Hold.$B$BLet op: als je een lid van de Orgrimmar Legion geneest of nuttige spreuken op hem uitspreekt, word je gemarkeerd voor PvP.",
  p = "Heb je je velddienst gedaan, $N? Captain Skullsplit is te vinden buiten Hive'Regal.",
  c = "Ik zie wel dat Krug weinig heeft met papierwerk. Hij heeft dit met silithid-bloed ondertekend!$B$BGoed dan, $N. Ik heb een reeks taken voorbereid die goed gebruikmaken van je vaardigheden als $c.$B$BDoor de voortdurende inzet van jou en mensen zoals jij wordt onze vijand snel verpletterd!",
  g = { {"velddienst", "field duty"}, {"deel", "share, part"}, {"Meld je", "report (zich melden)"}, {"bewijs", "proof"}, {"opdracht", "assignment"}, {"uit de buurt van", "away from"}, {"spanningen", "tensions (spanning)"}, {"vrijwilligers", "volunteers (vrijwilliger)"}, {"nuttige", "beneficial, useful (nuttig)"}, {"gemarkeerd", "flagged, marked (markeren)"}, {"weinig heeft met", "has little use for (weinig hebben met)"}, {"ondertekend", "signed (ondertekenen)"}, {"reeks", "set, series"}, {"voortdurende", "continued (voortdurend)"}, {"inzet", "efforts, commitment"}, {"verpletterd", "crushed (verpletteren)"} },
},

