  t = "De Orgrimmar Legion heeft mojo nodig!",
  d = "De Orgrimmar Legion heeft gevraagd om een paar ongewone ingrediënten. Gezien hun huidige prestaties in Silithus willen we zo snel mogelijk aan hun verzoek voldoen. Verzamel de materialen en breng ze naar de trol die Shai heet.",
  o = "Breng 6 Powerful Mojo, 6 Flasks of Big Mojo en 8 Oils of Immolation naar Shadow Priestess Shai bij Hive'Regal in Silithus. Je moet ook Logistics Task Briefing IV meebrengen om deze quest te voltooien.",
  p = "Heb je mijn materialen, $N?",
