[8815] = { en = "One Commendation Signet", tier = 4,
  t = "Eén erezegel",
  p = "Voor avonturiers die maar één erezegel hebben, ruil ik die voor een kleine hoeveelheid erkenning bij Orgrimmar.$B$BHoud er wel rekening mee dat het beter is om een stapel van tien zegels tegelijk in te leveren; je inspanningen krijgen dan meer erkenning. We bieden het ruilen van één zegel aan als service voor wie niet genoeg heeft voor een volle stapel van tien.$B$BDat gezegd hebbende: ik sta klaar om je te helpen als je toch één zegel wilt inleveren.",
