  p = "Voor avonturiers die maar één erezegel hebben, ruil ik die voor een kleine hoeveelheid erkenning bij Orgrimmar.$B$BHoud er wel rekening mee dat het beter is om een stapel van tien zegels tegelijk in te leveren; je inspanningen krijgen dan meer erkenning. We bieden het ruilen van één zegel aan als service voor wie niet genoeg heeft voor een volle stapel van tien.$B$BDat gezegd hebbende: ik sta klaar om je te helpen als je toch één zegel wilt inleveren.",
  c = "Goed dan. Je daden zijn in de archieven opgeschreven, en je krijgt de erkenning die je voor je inspanningen verdient. Ga zo door, $C.$B$BAls je nog meer zegels wilt inleveren, kan ik je daar ook verder mee helpen.",
  g = { {"erezegel", "commendation signet (honour seal)"}, {"ruil", "exchange (ruilen)"}, {"hoeveelheid", "amount"}, {"erkenning", "recognition"}, {"Houd er wel rekening mee", "please bear in mind (rekening houden met)"}, {"stapel", "stack"}, {"tegelijk", "at once, at the same time"}, {"in te leveren", "to hand in (inleveren)"}, {"inspanningen", "efforts (inspanning)"}, {"Dat gezegd hebbende", "with that being said"}, {"daden", "deeds (daad)"}, {"archieven", "records, archives (archief)"} },
},

[8841] = { en = "Ten Commendation Signets", tier = 4,
  t = "Tien erezegels",
  p = "Ik neem erezegels aan van avonturiers die ze tijdens hun plicht hebben gekregen. Voor elke set van tien die je mij geeft, zorg ik ervoor dat je daden bij Orgrimmar flink erkend worden. Ik neem ook losse zegels aan, maar die leveren veel minder erkenning op. We zijn veel meer geïnteresseerd in grotere daden van plicht, al wordt geen enkele daad genegeerd.$B$BDat gezegd hebbende: ik neem je zegels graag aan als je klaar bent om een set in te leveren.",
  c = "Uitstekend! Het is geen klein offer dat je hebt gebracht om deze zegels te verdienen, en je krijgt de erkenning die bij je dienst hoort. Het zijn avonturiers zoals jij, $N, die echt het verschil maken.$B$BLaat het me weten als je nog meer zegels wilt inleveren; ik help je graag met alle zegels die je wilt ruilen.",
  g = { {"erezegels", "commendation signets (erezegel)"}, {"plicht", "duty"}, {"erkend", "acknowledged, recognised (erkennen)"}, {"losse", "single, separate (los)"}, {"leveren", "yield (opleveren)"}, {"erkenning", "recognition"}, {"al wordt", "though ... is (al = although)"}, {"genegeerd", "ignored (negeren)"}, {"Dat gezegd hebbende", "with that being said"}, {"in te leveren", "to hand in (inleveren)"}, {"offer", "sacrifice"}, {"dienst", "service"}, {"het verschil maken", "make a difference"}, {"ruilen", "exchange"} },
},

