[9310] = { en = "Faint Necrotic Crystal", tier = 4,
  t = "Zwak necrotisch kristal",
  d = "Op het lijk van de verslagen wight vind je een kristal. Het straalt zwak necrotische energie uit.",
  o = "Breng de Faint Necrotic Crystal naar Lieutenant Rukag op de binnenplaats van de Undercity.",
  p = "Kan ik je ergens mee helpen?",
  c = "Zeg je dat dit is afgepakt van een wight die de stad aanviel?$b$bWe hebben bericht gekregen over de basiskampen van necropolissen die door de Scourge worden opgeroepen. Ik vermoed dat ze er een in de Undercity probeerden te maken. We zullen in de toekomst waakzaam moeten zijn.",
  g = { {"zwak", "faint, weak"}, {"necrotisch", "necrotic (deadly, of death magic)"}, {"lijk", "corpse"}, {"verslagen", "defeated, fallen (verslaan)"}, {"straalt", "radiates (uitstralen)"}, {"binnenplaats", "courtyard"}, {"afgepakt", "taken (away) (afpakken)"}, {"bericht", "word, message"}, {"basiskampen", "base camps (basiskamp)"}, {"necropolissen", "necropolises (necropolis)"}, {"opgeroepen", "summoned (oproepen)"}, {"vermoed", "suspect (vermoeden)"}, {"waakzaam", "vigilant, watchful"} },
},

[9330] = { en = "Stealing Stormwind's Flame", tier = 4,
  t = "De vlam van Stormwind stelen",
  d = "Deze vlam, gestolen uit het hart van Stormwind zelf, overspoelt je met warmte. Deze ruwe kracht is je vreemd, maar de Talespinner weet misschien meer...",
  o = "Breng de Flame of Stormwind terug naar de Festival Talespinner.",
  p = "Je straalt bijna, $R. Wat heb je daar?",
  c = "En dit fel brandende vuur... zeg je dat het uit Stormwind komt? Opmerkelijk! Dat moet een flink avontuur geweest zijn! Ik betaal je hier natuurlijk voor. Als je nog iets anders zoals dit vindt, kom dan zeker weer met me praten.",
  g = { {"gestolen", "stolen (stelen)"}, {"overspoelt", "floods (overspoelen)"}, {"ruwe", "raw (ruw)"}, {"is je vreemd", "is foreign to you (vreemd zijn)"}, {"straalt", "glow, shine (stralen)"}, {"fel", "brightly, fiercely"}, {"Opmerkelijk", "remarkable (opmerkelijk)"}, {"flink", "quite a, considerable"}, {"avontuur", "adventure"} },
},

