[9368] = { en = "The Festival of Fire", tier = 4,
  t = "Het vuurfestival",
  d = "Midsummer is weer aangebroken!$b$bZoals de traditie voorschrijft, worden er elk jaar Flamekeepers gekozen om de vreugdevuren in onze hoofdsteden te verzorgen. Overal in Azeroth branden vuren, maar het is van groot belang dat de onze het heetst en het helderst zijn, om het seizoen op de juiste manier eer te bewijzen.$b$bIk heb trouwens een taak voor je, als je het niet erg vindt. Ik heb nog niet gehoord of de vuren in alle hoofdsteden goed branden. Reis er zelf heen en warm je bij de vuren. Zorg dat ze heet zijn!",
  o = "Raak de vreugdevuren in Orgrimmar, Thunder Bluff en de Undercity aan, en praat daarna met een Festival Talespinner in de hoofdsteden.",
  p = "Heb je al geluk gehad, $N?",
  c = "Uitstekend! Het lijkt erop dat we dit jaar plichtsgetrouwe Flamekeepers hebben aangesteld, als de vreugdevuren zo goed verzorgd zijn als je zegt. Bedankt dat je ze voor me hebt gecontroleerd. Hier, neem dit aan als een klein teken van mijn waardering.",
  o1 = "Raak de Flame of Orgrimmar aan",
  o2 = "Raak de Flame of Thunder Bluff aan",
  o3 = "Raak de Flame of the Undercity aan",
  g = { {"aangebroken", "arrived, begun (aanbreken)"}, {"voorschrijft", "dictates, prescribes (voorschrijven)"}, {"vreugdevuren", "bonfires (vreugdevuur)"}, {"verzorgen", "tend, look after"}, {"van groot belang", "of great importance, imperative"}, {"helderst", "brightest (helder)"}, {"eer te bewijzen", "to pay homage, to honour (eer bewijzen)"}, {"Raak", "touch (aanraken)"}, {"plichtsgetrouwe", "dutiful (plichtsgetrouw)"}, {"aangesteld", "appointed (aanstellen)"}, {"verzorgd", "kept, looked after (verzorgen)"}, {"gecontroleerd", "checked, inspected (controleren)"}, {"waardering", "esteem, appreciation"} },
},

